const D = { energy: .62, density: .5, speed: 1, scale: 1, spread: .5, glow: .5, hue: 28, x: .5, y: .5, style: 'ethidium', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style, u = Math.min(width, height);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };

// ── palette per stain style ──
let ground, bandH, bandS, bandB, accentH, thin;
if (st === 'sybr')      { ground = [130,42,10]; bandH = 118; bandS = 92; bandB = 96; accentH = 96;  thin = false; }
else if (st === 'coomassie') { ground = [190,55,12]; bandH = 210; bandS = 84; bandB = 92; accentH = 200; thin = false; }
else if (st === 'silver')    { ground = [32,18,9];  bandH = 40;  bandS = 22; bandB = 96; accentH = 44;  thin = false; }
else if (st === 'densitometry'){ ground = [205,60,8]; bandH = 190; bandS = 78; bandB = 98; accentH = 190; thin = true; }
else /* ethidium */          { ground = [280,40,10]; bandH = ((P.hue%360)+360)%360; bandS = 90; bandB = 96; accentH = 320; thin = false; }

// ── lanes + seeded fingerprints ──
const lanes = Math.max(4, Math.round(5 + P.density*10));   // 5..15
if (S.seedUsed !== P.seed || S.lanes !== lanes || S.stKey !== st) {
  S.seedUsed = P.seed; S.lanes = lanes; S.stKey = st;
  S.fp = [];
  for (let l = 0; l < lanes; l++) {
    const isLadder = (l === 0 || l === lanes-1);
    const nb = isLadder ? 8 : (2 + Math.floor(fr(l*3.13)*4));   // ladder 8, samples 2..5
    const bands = [];
    for (let b = 0; b < nb; b++) {
      const mob = isLadder ? (0.1 + (b/(nb-1))*0.84) : (0.08 + fr(l*7.7 + b*2.31)*0.88);
      const inten = isLadder ? 0.7 : (0.42 + fr(l*5.31 + b*1.97)*0.58);
      const wob = 0.4 + fr(l*2.11 + b*3.7)*0.7;
      bands.push({ mob, inten, wob, jit: fr(l*13.1+b*4.7) });
    }
    S.fp.push({ isLadder, bands });
  }
}

// ── static gel ground buffer (adaptive resolution) ──
const BW = Math.max(360, Math.min(700, Math.round(width/2.4)));
const BH = Math.max(160, Math.round(BW*height/width));
const bkey = BW+'x'+BH+'|'+st+'|'+P.seed+'|'+lanes;
if (!S.bg || S.bkey !== bkey) {
  S.bkey = bkey;
  const g = S.bg || (S.bg = createGraphics(BW, BH));
  g.colorMode(g.HSB, 360, 100, 100, 100); g.pixelDensity(1);
  g.noStroke(); g.push();
  // base wash with subtle top→bottom gradient (loading front darker at top)
  for (let y = 0; y < BH; y++) {
    const f = y/BH;
    g.fill(ground[0], ground[1], ground[2]*(0.72+0.5*f), 100);
    g.rect(0, y, BW, 1);
  }
  // mottled buffer/agarose texture
  g.blendMode(g.ADD);
  for (let i = 0; i < 260; i++) {
    const x = fr(i*1.7)*BW, y = fr(i*2.9+7)*BH, r = (4+fr(i*3.3)*22)*(BW/500);
    g.fill(ground[0], ground[1]*0.6, ground[2]+8, 3+fr(i*4.1)*4);
    g.ellipse(x, y, r, r*0.7);
  }
  g.blendMode(g.BLEND);
  // lane dividers + wells
  const laneW = BW/lanes;
  g.stroke(ground[0], ground[1]*0.5, ground[2]*0.5, 40); g.strokeWeight(1);
  for (let l = 1; l < lanes; l++) g.line(l*laneW, 0, l*laneW, BH);
  g.noStroke();
  const wy = BH*0.045, wh = BH*0.03;
  for (let l = 0; l < lanes; l++) {
    g.fill(ground[0], ground[1]*0.7, ground[2]*0.35, 90);
    g.rect(l*laneW+laneW*0.16, wy, laneW*0.68, wh, 2);
  }
  g.pop();
}

// ── composite ground ──
push();
image(S.bg, 0, 0, width, height);

// ── migrating bands (drawn live on canvas) ──
const gelTop = height*0.10, gelBot = height*0.965, gelLen = gelBot - gelTop;
const laneW = width/lanes;
const runRate = 0.018 * (0.5 + P.speed);              // gel-lengths / sec at mob 1
const prog = Math.max(0, K.t) * runRate;
const drift = 0.6*Math.sin(K.t*0.61) + 0.4*Math.sin(K.t*1.37+1.7);   // subtle live shimmer
const beatGlow = 0.85 + K.pulse*0.35 + A.bass*0.5;
const thickBase = (thin ? 0.010 : 0.020) * (0.6 + P.spread*1.1) * P.scale;
const glowMul = 0.5 + P.glow*1.6;
const brt = (0.55 + P.energy*0.75);

blendMode(ADD); noStroke();
for (let l = 0; l < lanes; l++) {
  const xc = (l+0.5)*laneW, lane = S.fp[l];
  const bw = laneW*(lane.isLadder ? 0.60 : 0.74);
  for (let bi = 0; bi < lane.bands.length; bi++) {
    const bd = lane.bands[bi];
    let dist = (bd.mob * prog + bd.jit) % 1;            // wrap → perpetual run
    if (dist < 0) dist += 1;
    // edge fades: in near wells, out near bottom
    let fade = 1;
    if (dist < 0.07) fade = dist/0.07;
    else if (dist > 0.90) fade = (1 - dist)/0.10;
    const y = gelTop + dist*gelLen;
    // band broadens (diffuses) as it migrates
    const broad = 1 + dist*1.4;
    const th = Math.max(2, u*thickBase*bd.wob*broad);
    const shimmer = 0.75 + 0.25*Math.sin(K.t*0.9 + bi*1.7 + l + drift);
    const aCore = Math.min(100, 88*bd.inten*brt*fade*shimmer*beatGlow);
    if (aCore < 1) continue;
    const isL = lane.isLadder;
    const hh = isL ? accentH : bandH;
    // glow halo (2 translucent layers)
    fill(hh, bandS*0.8, bandB, aCore*0.22);
    rect(xc-bw/2, y-th*1.9*glowMul, bw, th*3.8*glowMul, th);
    fill(hh, bandS*0.9, bandB, aCore*0.42);
    rect(xc-bw/2, y-th*0.95, bw, th*1.9, th*0.6);
    // core
    fill(hh, bandS, Math.min(100, bandB+4), aCore);
    rect(xc-bw*0.46, y-th*0.5, bw*0.92, th, th*0.5);
    // densitometry: add a right-edge intensity tick
    if (thin) { fill(hh, bandS*0.6, bandB, aCore*0.5); rect(xc-bw/2, y-1, bw*(0.3+0.6*bd.inten), 2); }
  }
}

// densitometry scan grid overlay
if (thin) {
  blendMode(ADD); stroke(accentH, 40, 60, 10); strokeWeight(1);
  for (let gy = 0; gy < 14; gy++) { const y = gelTop + gy/14*gelLen; line(0, y, width, y); }
  noStroke();
}
pop();

blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
if (P.alpha < 100) { push(); blendMode(BLEND); noStroke(); fill(0,0,0,100-P.alpha); rect(0,0,width,height); pop(); }
